<div class="stu-dialog-layer" id="studentDialog" aria-hidden="true">
    <div class="stu-dialog-backdrop" data-stu-dialog-dismiss></div>
    <section class="stu-dialog" role="dialog" aria-modal="true" aria-labelledby="studentDialogTitle" aria-describedby="studentDialogMessage" tabindex="-1">
        <div class="stu-dialog-handle" aria-hidden="true"></div>
        <div class="stu-dialog-icon" id="studentDialogIcon"><i class="bi bi-info-lg"></i></div>
        <div class="stu-dialog-copy">
            <span class="stu-dialog-eyebrow" id="studentDialogEyebrow">Student portal</span>
            <h2 id="studentDialogTitle">Information</h2>
            <p id="studentDialogMessage"></p>
        </div>
        <div class="stu-dialog-actions">
            <button type="button" class="stu-dialog-button secondary" id="studentDialogCancel">Cancel</button>
            <button type="button" class="stu-dialog-button primary" id="studentDialogConfirm">Okay</button>
        </div>
    </section>
</div>

<style>
.stu-dialog-layer{position:fixed!important;inset:0!important;z-index:2500!important;width:100%!important;height:100dvh!important;display:flex!important;align-items:flex-end!important;justify-content:center!important;padding:16px max(14px,env(safe-area-inset-right)) calc(16px + env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-left))!important;visibility:hidden!important;opacity:0!important;pointer-events:none!important;transition:opacity .2s ease,visibility .2s ease!important}.stu-dialog-layer.is-open{visibility:visible!important;opacity:1!important;pointer-events:auto!important}.stu-dialog-backdrop{position:absolute!important;inset:0!important;background:rgba(12,20,39,.62)!important;backdrop-filter:blur(4px)!important;-webkit-backdrop-filter:blur(4px)!important}.stu-dialog{position:relative!important;z-index:1!important;width:min(100%,420px)!important;max-width:420px!important;margin:0 auto!important;padding:11px 16px 16px!important;border:1px solid #e6eaf2!important;border-radius:22px!important;color:#253858!important;background:#fff!important;box-shadow:0 24px 70px rgba(12,20,39,.3)!important;transform:translateY(24px) scale(.98)!important;transition:transform .24s cubic-bezier(.22,.8,.25,1)!important;outline:0!important}.stu-dialog-layer.is-open .stu-dialog{transform:translateY(0) scale(1)!important}.stu-dialog-handle{width:38px!important;height:4px!important;margin:0 auto 14px!important;border-radius:99px!important;background:#dce2eb!important}.stu-dialog-icon{width:50px!important;height:50px!important;margin:0 auto 11px!important;display:grid!important;place-items:center!important;border-radius:16px!important;color:#3156d3!important;background:#e8eeff!important;font-size:23px!important}.stu-dialog-icon.success{color:#139466!important;background:#e4f8ef!important}.stu-dialog-icon.error{color:#d14d4d!important;background:#ffeceb!important}.stu-dialog-icon.warning{color:#d78a00!important;background:#fff4dc!important}.stu-dialog-icon.info{color:#3156d3!important;background:#e8eeff!important}.stu-dialog-copy{text-align:center!important}.stu-dialog-eyebrow{display:block!important;margin-bottom:3px!important;color:#98a2b3!important;font-size:8px!important;line-height:1.2!important;font-weight:700!important;text-transform:uppercase!important;letter-spacing:.1em!important}.stu-dialog-copy h2{margin:0!important;color:#253858!important;font-size:17px!important;line-height:1.3!important;font-weight:750!important}.stu-dialog-copy p{margin:7px auto 0!important;max-width:320px!important;color:#667085!important;font-size:11px!important;line-height:1.5!important;white-space:pre-line!important;word-break:break-word!important}.stu-dialog-actions{display:flex!important;gap:8px!important;margin-top:17px!important}.stu-dialog-button{min-height:44px!important;flex:1!important;margin:0!important;padding:9px 12px!important;border-radius:12px!important;font-size:11px!important;line-height:1.2!important;font-weight:700!important;cursor:pointer!important}.stu-dialog-button.primary{border:1px solid #3156d3!important;color:#fff!important;background:linear-gradient(135deg,#4169e1,#294bb4)!important;box-shadow:0 7px 16px rgba(49,86,211,.2)!important}.stu-dialog-button.primary.danger{border-color:#d14d4d!important;background:linear-gradient(135deg,#e06060,#bd3f3f)!important;box-shadow:0 7px 16px rgba(209,77,77,.18)!important}.stu-dialog-button.secondary{border:1px solid #e2e7ef!important;color:#536176!important;background:#f7f9fc!important}.stu-dialog-button:active{transform:scale(.98)!important}.stu-dialog-button:focus-visible,.stu-dialog:focus-visible{outline:3px solid rgba(49,86,211,.18)!important;outline-offset:2px!important}body.stu-dialog-lock{overflow:hidden!important}
:root[data-theme="dark"] .stu-dialog{color:#e7ecf4!important;background:#1b2433!important;border-color:#303b4c!important}:root[data-theme="dark"] .stu-dialog-handle{background:#3b4657!important}:root[data-theme="dark"] .stu-dialog-copy h2{color:#f2f5fb!important}:root[data-theme="dark"] .stu-dialog-copy p{color:#aab4c3!important}:root[data-theme="dark"] .stu-dialog-button.secondary{color:#c4ccda!important;background:#242f42!important;border-color:#354158!important}:root[data-theme="dark"] .stu-dialog-icon.info{background:#24365f!important;color:#9db2ff!important}:root[data-theme="dark"] .stu-dialog-icon.success{background:#193c34!important;color:#76dcb4!important}:root[data-theme="dark"] .stu-dialog-icon.warning{background:#3d321c!important;color:#f0bd62!important}:root[data-theme="dark"] .stu-dialog-icon.error{background:#3a2429!important;color:#ff9292!important}
@media(min-width:600px){.stu-dialog-layer{align-items:center!important}.stu-dialog-handle{display:none!important}.stu-dialog{padding-top:20px!important}}
@media(prefers-reduced-motion:reduce){.stu-dialog-layer,.stu-dialog{transition:none!important}}
</style>

<script>
(function(){
    var layer=document.getElementById('studentDialog'),dialog=layer.querySelector('.stu-dialog'),icon=document.getElementById('studentDialogIcon'),title=document.getElementById('studentDialogTitle'),message=document.getElementById('studentDialogMessage'),eyebrow=document.getElementById('studentDialogEyebrow'),confirmButton=document.getElementById('studentDialogConfirm'),cancelButton=document.getElementById('studentDialogCancel');
    var resolver=null,timerId=null,lastFocus=null,allowDismiss=true;
    var types={success:['bi-check-lg','Success'],error:['bi-x-lg','Something went wrong'],warning:['bi-exclamation-lg','Please confirm'],info:['bi-info-lg','Student portal']};
    function finish(confirmed,reason){if(!layer.classList.contains('is-open'))return;clearTimeout(timerId);layer.classList.remove('is-open');layer.setAttribute('aria-hidden','true');document.body.classList.remove('stu-dialog-lock');var done=resolver;resolver=null;setTimeout(function(){if(lastFocus&&document.contains(lastFocus))lastFocus.focus();if(done)done({isConfirmed:confirmed,isDismissed:!confirmed,dismiss:reason||null})},210)}
    function open(options){options=options||{};if(resolver)finish(false,'replaced');var type=types[options.type] ? options.type : (types[options.icon]?options.icon:'info'),meta=types[type];lastFocus=document.activeElement;allowDismiss=options.allowDismiss!==false;icon.className='stu-dialog-icon '+type;icon.innerHTML='<i class="bi '+meta[0]+'"></i>';eyebrow.textContent=options.eyebrow||meta[1];title.textContent=options.title||meta[1];message.textContent=options.message||options.text||'';message.style.display=message.textContent?'block':'none';confirmButton.textContent=options.confirmText||options.confirmButtonText||'Okay';cancelButton.textContent=options.cancelText||options.cancelButtonText||'Cancel';cancelButton.style.display=options.showCancel||options.showCancelButton?'block':'none';confirmButton.style.display=options.showConfirm===false||options.showConfirmButton===false?'none':'block';confirmButton.classList.toggle('danger',options.danger===true);layer.classList.add('is-open');layer.setAttribute('aria-hidden','false');document.body.classList.add('stu-dialog-lock');requestAnimationFrame(function(){(confirmButton.style.display==='none'?dialog:confirmButton).focus()});if(Number(options.timer)>0)timerId=setTimeout(function(){finish(false,'timer')},Number(options.timer));return new Promise(function(resolve){resolver=resolve})}
    confirmButton.addEventListener('click',function(){finish(true,'confirm')});cancelButton.addEventListener('click',function(){finish(false,'cancel')});layer.querySelector('[data-stu-dialog-dismiss]').addEventListener('click',function(){if(allowDismiss)finish(false,'backdrop')});document.addEventListener('keydown',function(event){if(!layer.classList.contains('is-open'))return;if(event.key==='Escape'&&allowDismiss){event.preventDefault();finish(false,'escape');return}if(event.key==='Tab'){var items=Array.from(dialog.querySelectorAll('button:not([style*="display: none"])'));if(!items.length)return;var first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
    window.StudentModal={open:open,close:function(){finish(false,'close')},success:function(titleText,text){return open({type:'success',title:titleText,message:text})},error:function(titleText,text){return open({type:'error',title:titleText,message:text})},confirm:function(options){options=options||{};options.type=options.type||'warning';options.showCancel=true;return open(options)}};
})();
</script>
